def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = set()
            while q:
                y, x = q.popleft()
                comp.add((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append(comp)

    def edge_enclosed(comp):
        # A background run on an edge is enclosed when its run is capped
        # by foreground cells at both ends of that edge.
        sides = [
            ([(0, c) for c in range(w)], w),
            ([(h-1, c) for c in range(w)], w),
            ([(r, 0) for r in range(h)], h),
            ([(r, w-1) for r in range(h)], h),
        ]
        for cells, n in sides:
            positions = [i for i, p in enumerate(cells) if p in comp]
            if not positions:
                continue
            runs = []
            start = prev = positions[0]
            for i in positions[1:]:
                if i != prev + 1:
                    runs.append((start, prev))
                    start = i
                prev = i
            runs.append((start, prev))
            for a, b in runs:
                left_capped = a > 0 and grid[cells[a-1][0]][cells[a-1][1]] != background
                right_capped = b < n-1 and grid[cells[b+1][0]][cells[b+1][1]] != background
                if left_capped and right_capped:
                    return True
        return False

    out = [row[:] for row in grid]
    for comp in components:
        touches_edge = any(r in (0, h-1) or c in (0, w-1) for r, c in comp)
        if not touches_edge or edge_enclosed(comp):
            for r, c in comp:
                out[r][c] = 4
    return out
